 1	import { component$, useComputed$, useSignal } from "@qwik.dev/core";
 2	import type { ManualGuide } from "./manual-guide-types";
 3	
 4	/** A real application view paired with one deliberate action at a time. */
 5	export const ManualWalkthrough = component$<{ id: string; guide: ManualGuide }>(
 6	  ({ id, guide }) => {
 7	    const selected = useSignal(0);
 8	    const step = useComputed$(() => guide.steps[selected.value]);
 9	    if (!guide.steps.length) return null;
10	
11	    return (
12	      <figure class="manual-walkthrough" aria-labelledby={`${id}-guide-title`}>
13	        <figcaption class="manual-walkthrough-heading">
14	          <p class="manual-plate-label">At the desk · A visual walkthrough</p>
15	          <h3 id={`${id}-guide-title`}>{guide.title}</h3>
16	          <p>{guide.summary}</p>
17	        </figcaption>
18	        <ol
19	          class="manual-walkthrough-steps"
20	          aria-label={`${guide.title}: steps`}
21	        >
22	          {guide.steps.map((item, index) => (
23	            <li key={item.title}>
24	              <button
25	                type="button"
26	                aria-pressed={selected.value === index}
27	                aria-controls={`${id}-guide-instruction`}
28	                onClick$={() => (selected.value = index)}
29	              >
30	                <span class="manual-step-number" aria-hidden="true">
31	                  {String(index + 1).padStart(2, "0")}
32	                </span>
33	                {item.title}
34	              </button>
35	            </li>
36	          ))}
37	        </ol>
38	        <div class="manual-walkthrough-image">
39	          <a
40	            href={step.value.image}
41	            target="_blank"
42	            rel="noopener noreferrer"
43	            aria-label={`Open full-size view: ${step.value.title}`}
44	          >
45	            <img
46	              src={step.value.image}
47	              alt={step.value.alt}
48	              width={step.value.width}
49	              height={step.value.height}
50	              loading="lazy"
51	              decoding="async"
52	            />
53	            <span class="manual-walkthrough-enlarge" aria-hidden="true">
54	              Open full-size ↗
55	            </span>
56	          </a>
57	        </div>
58	        <div
59	          class="manual-walkthrough-instruction"
60	          id={`${id}-guide-instruction`}
61	          aria-live="polite"
62	          aria-atomic="true"
63	        >
64	          <p class="manual-step-position">
65	            Step {selected.value + 1} of {guide.steps.length}
66	          </p>
67	          <h4>{step.value.title}</h4>
68	          <p>{step.value.instruction}</p>
69	        </div>
70	        {guide.note && <p class="manual-walkthrough-note">{guide.note}</p>}
71	        <details class="manual-written-steps">
72	          <summary>Read all the steps</summary>
73	          <ol>
74	            {guide.steps.map((item) => (
75	              <li key={item.title}>
76	                <strong>{item.title}.</strong> {item.instruction}
77	              </li>
78	            ))}
79	          </ol>
80	        </details>
81	        <div class="manual-print-steps">
82	          <ol>
83	            {guide.steps.map((item) => (
84	              <li key={item.title}>
85	                <strong>{item.title}.</strong> {item.instruction}
86	              </li>
87	            ))}
88	          </ol>
89	        </div>
90	      </figure>
91	    );
92	  },
93	);

