  1	import { createServer } from "node:http";
  2	import { createReadStream } from "node:fs";
  3	import { stat } from "node:fs/promises";
  4	import { extname, join } from "node:path";
  5	import { fileURLToPath } from "node:url";
  6	import { installLiveVoiceRelay } from "./scripts/live-voice-relay.mjs";
  7	
  8	// Railway terminates TLS at its edge. Let Qwik validate browser origins using
  9	// the edge's protocol rather than the container's internal HTTP connection.
 10	// Keep explicit deployment overrides and local direct-server behavior intact.
 11	if (process.env.RAILWAY_ENVIRONMENT_ID && !process.env.PROTOCOL_HEADER) {
 12	  process.env.PROTOCOL_HEADER = "x-forwarded-proto";
 13	}
 14	
 15	const DIST_ROOT = fileURLToPath(new URL("./dist/", import.meta.url));
 16	const ROOT_FILE_TYPES = {
 17	  ".ico": "image/x-icon",
 18	  ".js": "application/javascript; charset=utf-8",
 19	  ".jpg": "image/jpeg",
 20	  ".json": "application/json; charset=utf-8",
 21	  ".pdf": "application/pdf",
 22	  ".png": "image/png",
 23	  ".mp4": "video/mp4",
 24	  ".svg": "image/svg+xml; charset=utf-8",
 25	  ".txt": "text/plain; charset=utf-8",
 26	  ".vtt": "text/vtt; charset=utf-8",
 27	};
 28	
 29	async function serveRootStaticFile(req, res, next) {
 30	  if (req.method !== "GET" && req.method !== "HEAD") return next();
 31	
 32	  const pathname = new URL(req.url ?? "/", "http://localhost").pathname;
 33	  let filename;
 34	  try {
 35	    filename = decodeURIComponent(pathname.slice(1));
 36	  } catch {
 37	    return next();
 38	  }
 39	  const launchMedia = /^assets\/launch\/the-room-(en|fr)\.(mp4|jpg|vtt)$/.test(
 40	    filename,
 41	  );
 42	  const manualMedia =
 43	    /^assets\/manual\/(roll-call|edited|newsreel|the-strike|sting|house-context|source-workspace)\.(mp4|jpg|vtt)$/.test(
 44	      filename,
 45	    );
 46	  if (
 47	    !filename ||
 48	    (!launchMedia && !manualMedia && filename.includes("/")) ||
 49	    filename.includes("\\")
 50	  ) {
 51	    return next();
 52	  }
 53	
 54	  const filePath = join(DIST_ROOT, filename);
 55	  try {
 56	    const details = await stat(filePath);
 57	    if (!details.isFile()) return next();
 58	
 59	    const contentType = ROOT_FILE_TYPES[extname(filename).toLowerCase()];
 60	    if (contentType) res.setHeader("Content-Type", contentType);
 61	    res.setHeader("Content-Length", details.size);
 62	    res.setHeader(
 63	      "Cache-Control",
 64	      filename === "service-worker.js" || filename === "manifest.json"
 65	        ? "no-cache"
 66	        : "public, max-age=3600",
 67	    );
 68	    // The router's static middleware sends entire files. Native video seeking
 69	    // needs byte ranges for the launch film and contextual manual videos.
 70	    if ((launchMedia || manualMedia) && extname(filename) === ".mp4") {
 71	      res.setHeader("Accept-Ranges", "bytes");
 72	      if (req.method === "GET" && req.headers.range) {
 73	        const range = /^bytes=(\d*)-(\d*)$/.exec(req.headers.range);
 74	        let start = range?.[1] ? Number(range[1]) : 0;
 75	        let end = range?.[2] ? Number(range[2]) : details.size - 1;
 76	        if (range && !range[1] && range[2]) {
 77	          start = Math.max(0, details.size - Number(range[2]));
 78	          end = details.size - 1;
 79	        }
 80	        if (
 81	          !range ||
 82	          (!range[1] && !range[2]) ||
 83	          !Number.isSafeInteger(start) ||
 84	          !Number.isSafeInteger(end) ||
 85	          start >= details.size ||
 86	          end < start
 87	        ) {
 88	          res.setHeader("Content-Range", `bytes */${details.size}`);
 89	          res.setHeader("Content-Length", 0);
 90	          res.writeHead(416);
 91	          return res.end();
 92	        }
 93	        end = Math.min(end, details.size - 1);
 94	        res.setHeader("Content-Range", `bytes ${start}-${end}/${details.size}`);
 95	        res.setHeader("Content-Length", end - start + 1);
 96	        res.writeHead(206);
 97	        const stream = createReadStream(filePath, { start, end });
 98	        stream.on("error", () => res.destroy());
 99	        res.on("close", () => stream.destroy());
100	        return stream.pipe(res);
101	      }
102	    }
103	    if (filename === "service-worker.js") {
104	      res.setHeader("Service-Worker-Allowed", "/");
105	    }
106	    res.writeHead(200);
107	    if (req.method === "HEAD") return res.end();
108	    createReadStream(filePath).pipe(res);
109	  } catch (error) {
110	    if (error?.code === "ENOENT" || error?.code === "ENOTDIR") return next();
111	    next(error);
112	  }
113	}
114	
115	async function main() {
116	  try {
117	    const mod = await import("./server/entry.preview.js");
118	    const { router, notFound, staticFile } = mod.default ? mod.default : mod;
119	
120	    const server = createServer((req, res) => {
121	      serveRootStaticFile(req, res, (rootStaticError) => {
122	        if (rootStaticError) {
123	          console.error(rootStaticError);
124	          res.writeHead(500, { "Content-Type": "text/plain" });
125	          res.end("Internal Server Error");
126	          return;
127	        }
128	
129	        if (staticFile) {
130	          staticFile(req, res, () => {
131	            router(req, res, () => {
132	              notFound(req, res, () => {
133	                res.writeHead(404, { "Content-Type": "text/plain" });
134	                res.end("Not Found");
135	              });
136	            });
137	          });
138	        } else {
139	          router(req, res, () => {
140	            notFound(req, res, () => {
141	              res.writeHead(404, { "Content-Type": "text/plain" });
142	              res.end("Not Found");
143	            });
144	          });
145	        }
146	      });
147	    });
148	
149	    installLiveVoiceRelay(server);
150	    const port = parseInt(process.env.PORT || "3000", 10);
151	    server.listen(port, "0.0.0.0", () => {
152	      console.log(`Twyne server listening on 0.0.0.0:${port}`);
153	    });
154	  } catch (err) {
155	    console.error("Failed to start server:", err);
156	    process.exit(1);
157	  }
158	}
159	
160	main();

