  font: 500 0.75rem/1.5 var(--font-sans);
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.manual-walkthrough-heading h3 {
  margin: 0 0 0.5rem;
  font: 600 1.125rem/1.5 var(--font-display);
}

.manual-walkthrough-heading > p:last-child {
  margin: 0;
  color: var(--color-ink-light);
  font-size: 0.9375rem;
}

.manual-walkthrough-image {
  position: relative;
  background: var(--color-paper-2);
  padding-top: 1rem;
}

.manual-walkthrough-image a {
  display: block;
}

.manual-walkthrough-image img {
  display: block;
  width: auto;
  max-width: 100%;
  height: auto;
  max-height: 40rem;
  margin-inline: auto;
  object-fit: contain;
  border: 1px solid var(--color-paper-3);
}

.manual-walkthrough-enlarge {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  min-height: 2.75rem;
  padding: 0.5rem 0.75rem;
  color: var(--color-ink);
  font: 500 0.75rem/1.4 var(--font-sans);
  pointer-events: none;
}

.manual-walkthrough-steps {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0;
  list-style: none;
  margin: 0;
  padding: 0;
  border-bottom: 1px solid var(--color-paper-3);
}

.manual-walkthrough-steps button {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  width: 100%;
  min-height: 3.5rem;
  padding: 0.625rem 0.75rem;
  border: 0;
  background: transparent;
  color: var(--color-ink-light);
  font: 500 0.8125rem/1.5 var(--font-sans);
  text-align: left;
  cursor: pointer;
}

.manual-walkthrough-steps button:hover {
  background: var(--color-paper);
}

.manual-walkthrough-steps button[aria-pressed="true"] {
  background: var(--color-paper-2);
  color: var(--color-ink);
  text-decoration: underline;
  text-decoration-color: var(--color-vermilion);
  text-underline-offset: 0.25em;
}

.manual-step-number {
  color: var(--color-vermilion);
  font-variant-numeric: tabular-nums;
  font-weight: 600;
  flex-shrink: 0;
}

.manual-walkthrough-instruction {
  padding: 1.25rem 0 0.75rem;
}

.manual-walkthrough-instruction h4 {
  margin: 0 0 0.5rem;
  font: 600 1rem/1.5 var(--font-sans);
}

.manual-walkthrough-instruction > p:last-child {
  margin: 0;
  font-size: 0.9375rem;
  line-height: 1.75;
}

.manual-walkthrough-note {
  margin: 0 0 0.75rem;
  color: var(--color-ink-light);
  font: italic 0.8125rem/1.6 var(--font-serif);
}

.manual-written-steps,
.manual-video-transcript {
  font-size: 0.9375rem;
}

.manual-written-steps summary,
.manual-video-transcript summary {
  display: list-item;
  min-height: 2.75rem;
  padding: 0.5rem 0;
  cursor: pointer;
  font: 500 0.8125rem/1.5 var(--font-sans);
}

.manual-written-steps ol {
  margin: 0.5rem 0 1.25rem;
  padding-left: 1.5rem;
}

.manual-written-steps li + li {
  margin-top: 0.75rem;
}

.manual-print-steps {
  display: none;
}

.manual-video {
  margin: 1.25rem 0;
  border-block: 1px solid var(--color-paper-3);
}

.manual-video > summary {
  display: flex;
  align-items: center;
  gap: 0.75rem;
  min-height: 3.25rem;
  padding: 0.75rem 0.125rem;
  cursor: pointer;
  font: 500 0.875rem/1.5 var(--font-sans);
}

.manual-video > summary::before {
  content: "▶";
  color: var(--color-vermilion);
  font-size: 0.75rem;
  flex-shrink: 0;
}

.manual-video[open] > summary::before {
  content: "▾";
}

.manual-video-watch {
  color: var(--color-ink-light);
  font-weight: 400;
}

.manual-video-name {
  flex: 1;
}

.manual-video-duration {
  color: var(--color-ink-light);
  font-size: 0.75rem;
  white-space: nowrap;
  font-variant-numeric: tabular-nums;
}

.manual-video figure {
  margin: 0;
  padding: 0.25rem 0 1rem;
}

.manual-video figcaption p,
.manual-video-transcript p {
  margin: 0 0 1rem;
  color: var(--color-ink-light);
  font-size: 0.9375rem;
}

.manual-video video {
  display: block;
  width: 100%;
  height: auto;
  background: #181512;
}

.manual-video-portrait video {
  width: min(100%, 17rem);
  max-height: 30rem;
  margin-inline: auto;
}

.manual-video-footer {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 0 1rem;
  padding-top: 0.5rem;
  font: 0.75rem/1.6 var(--font-sans);
}

.manual-video-footer p {
  margin: 0;
  color: var(--color-ink-light);
}

.manual-video-footer a {
  display: inline-flex;
  align-items: center;
  min-height: 2.75rem;
}

@media (prefers-reduced-motion: reduce) {
  .twyne-manual :is(a, input) {
    transition: none;
  }
}

@media (max-width: 960px) {
  .manual-shell {
    padding-inline: 1.5rem;
  }
  .manual-layout {
    grid-template-columns: 13rem minmax(0, 1fr);
    gap: 2rem;
  }
}

@media (max-width: 720px) {
  .manual-shell {
    padding: 1.5rem 1.25rem 2.5rem;
  }
  .manual-masthead {
    display: block;
    margin-bottom: 1.5rem;
    padding-bottom: 1.5rem;
  }
  .manual-masthead h1 {
    font-size: 2.25rem;
  }
  .manual-desk-link {
    margin-top: 1.25rem;
  }
  .manual-layout {
    display: block;
  }
  .manual-contents {
    position: static;
    max-height: none;
    overflow: visible;
    padding: 0 0 1.5rem;
    margin-bottom: 2rem;
    border-bottom: 1px solid var(--color-paper-3);
  }
  .manual-contents summary {
    min-height: 2.75rem;
  }
  .manual-desktop-contents {
    display: none;
  }
  .manual-mobile-contents {
    display: block;
  }
  .manual-contents-groups {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 1.25rem 1rem;
  }
  .manual-contents-group + .manual-contents-group {
    margin-top: 0;
  }
  .twyne-manual .toc-link {
    min-height: 2.75rem;
  }
  .manual-content {
    max-width: none;
  }
  .manual-section {
    margin-bottom: 2rem;
    padding-bottom: 2rem;
  }
  .manual-h2 {
    font-size: 1.5rem;
  }
  .manual-inheritance {
    grid-template-columns: 1fr;
  }
  .manual-inheritance li + li {
    border-left: 0;
    border-top: 1px solid var(--color-paper-3);
  }
  .manual-terms > div {
    grid-template-columns: 6rem minmax(0, 1fr);
    gap: 0.75rem;
  }
  .manual-callout {
    padding: 1rem;
  }
  .manual-walkthrough-steps {
    grid-template-columns: 1fr;
  }
  .manual-walkthrough-steps button {
    min-height: 2.75rem;
  }
  .manual-video > summary {
    gap: 0.5rem;
  }
  .manual-video-watch {
    display: none;
  }
}

@media print {
  .manual-shell {
    padding: 0;
  }
  .manual-layout {
    display: block;
  }
  .manual-content {
    max-width: none;
  }
  .manual-contents,
  .manual-desk-link,
  .manual-colophon,
  .manual-skip,
  .manual-video,
  .manual-walkthrough-steps,
  .manual-walkthrough-instruction,
  .manual-walkthrough-enlarge,
  .manual-written-steps,
  #launch-film,
  .manual-platform {
    display: none;
  }
  .manual-h2,
  .manual-h3 {
    break-after: avoid;
  }
  .manual-callout,
  .manual-inheritance {
    break-inside: avoid;
  }
  .manual-print-steps {
    display: block;
  }
  .manual-print-steps li + li {
    margin-top: 0.75rem;
  }
  .manual-walkthrough-image {
    break-inside: avoid;
  }
}

