 await page.locator('.manual-mobile-contents > summary').click();
 const mobile=await page.evaluate(()=>({width:innerWidth,scrollWidth:document.documentElement.scrollWidth}));
 await page.screenshot({path:`${dir}/mobile.png`,fullPage:false});
 const reports={initial,steps,print,mobile,errors,requests};
 await fs.writeFile(`${dir}/review-initial.json`,JSON.stringify(reports,null,2));
 console.log(JSON.stringify(reports));
 const video=page.video(); await context.close(); console.log('recording',await video.path()); await browser.close();
})().catch(e=>{console.error(e);process.exitCode=1});
