const buttons=guide.locator('.manual-walkthrough-steps button');for(let i=0;i<await buttons.count();i++){await buttons.nth(i).focus();await page.keyboard.press(i%2===0?'Enter':'Space');await page.waitForTimeout(100);const state=await guide.evaluate(g=>({title:g.querySelector('h3').textContent,pressed:[...g.querySelectorAll('button')].map(b=>b.getAttribute('aria-pressed')),step:g.querySelector('.manual-step-position').textContent,image:g.querySelector('img').getAttribute('src'),instruction:g.querySelector('h4').textContent,buttonFocus:document.activeElement.tagName==='BUTTON'}));steps.push({i,...state});}
}console.log('steps checked',steps.length,'mismatches',JSON.stringify(steps.filter(s=>s.pressed[s.i]!=='true'||!s.step.includes(`Step ${s.i+1} of`))));
const dv=page.locator('#getting-started .manual-video');await dv.locator(':scope > summary').click();await dv.locator('video').evaluate(v=>v.play());await page.waitForTimeout(300);const aPlaying=await dv.locator('video').evaluate(v=>!v.paused);await page.locator('#dossier .manual-video > summary').click();await page.locator('#dossier video').evaluate(v=>v.play());await page.waitForTimeout(300);const afterOther=await dv.locator('video').evaluate(v=>v.paused);await page.locator('#dossier .manual-video > summary').click();await page.waitForTimeout(300);const closed=await page.locator('#dossier video').evaluate(v=>v.paused);
await dv.locator('video').evaluate(v=>v.play());await page.locator('.manual-desktop-contents a[href="#house"]').click();await page.waitForTimeout(300);const hashPaused=await dv.locator('video').evaluate(v=>v.paused);console.log('video',JSON.stringify({aPlaying,afterOther,closed,hashPaused}));
await page.emulateMedia({media:'print'});const print=await page.evaluate(()=>({printSteps:[...document.querySelectorAll('.manual-print-steps')].filter(e=>getComputedStyle(e).display!=='none').length,stepButtons:[...document.querySelectorAll('.manual-walkthrough-steps')].filter(e=>getComputedStyle(e).display!=='none').length,videos:[...document.querySelectorAll('video')].filter(e=>e.getBoundingClientRect().height>0).length,images:[...document.querySelectorAll('.manual-walkthrough img')].map(e=>({src:e.getAttribute('src'),loaded:e.complete&&e.naturalWidth>0}))}));await page.pdf({path:`${dir}/manual-print.pdf`,format:'A4',printBackground:true});console.log('print',JSON.stringify(print));
await page.emulateMedia({media:'screen'});await page.setViewportSize({width:390,height:844});await page.goto('http://127.0.0.1:5180/docs/',{waitUntil:'domcontentloaded'});await page.locator('.manual-mobile-contents > summary').click();const mobile=await page.evaluate(()=>({width:innerWidth,scrollWidth:document.documentElement.scrollWidth}));await page.screenshot({path:`${dir}/mobile.png`});await page.setViewportSize({width:1440,height:1000});await page.locator('#privacy').scrollIntoViewIfNeeded();await page.screenshot({path:`${dir}/desktop-privacy.png`});await fs.writeFile(`${dir}/review-behavior.json`,JSON.stringify({initial,steps,video:{aPlaying,afterOther,closed,hashPaused},print,mobile,errors,mediaRequests},null,2));console.log('mobile',mobile,'errors',errors);
}finally{const video=page.video();await context.close();console.log('recording',await video.path());await browser.close();}})().catch(e=>{console.error(e);process.exitCode=1});
