                  <h1
                    id="refinery-title"
                    class="mt-4 leading-[1.05] text-[var(--color-ink)]"
                    style="font-family: var(--font-display); font-weight: 700; font-size: 2rem; letter-spacing: -0.015em;"
                  >
                    Refine the{" "}
                    <em style="color: var(--color-vermilion); font-style: italic;">
