.twyne-manual {
  min-height: 100vh;
  background: var(--color-paper-soft);
  color: var(--color-ink);
  font: 1rem/1.75 var(--font-serif);
}

.manual-shell {
  max-width: 76rem;
  margin: 0 auto;
  padding: 3rem 2.5rem 4rem;
}

.manual-masthead {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 2rem;
  padding-bottom: 2.5rem;
  margin-bottom: 3rem;
  border-bottom: 3px double var(--color-ink);
}

.manual-eyebrow,
.manual-chapter {
  margin: 0 0 1rem;
  color: var(--color-ink-light);
  font: 500 0.875rem/1.4 var(--font-sans);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.manual-masthead h1 {
  margin: 0;
  font: 700 3rem/1.2 var(--font-display);
  letter-spacing: -0.035em;
}

.manual-deck {
  max-width: 52ch;
  margin: 1rem 0 0;
  color: var(--color-ink-light);
  font: italic 1.0625rem/1.7 var(--font-serif);
}

.manual-desk-link {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  min-height: 2.75rem;
  font: 500 0.875rem/1.4 var(--font-sans);
}

.manual-layout {
  display: grid;
  grid-template-columns: 15.5rem minmax(0, 1fr);
  align-items: start;
  gap: 4rem;
}

.manual-contents {
  position: sticky;
  top: 1.5rem;
